<script setup lang="ts">
import {History,Flame,Plus,Monitor,Play,Square,ArrowLeft,ChevronRight,Settings2,Blocks,Users,BookOpen,ScrollText,Copy,Check,RefreshCw,FolderOpen,Download,ShieldCheck,KeyRound,TriangleAlert,Wifi,LoaderCircle} from 'lucide-vue-next';
import {invoke} from '../bridge';
import {useDesktop} from '../useDesktop';
import ConnectionProfiles from './ConnectionProfiles.vue';
import ModuleVersions from './ModuleVersions.vue';
import FirstTable from './FirstTable.vue';
import ConnectionShare from './ConnectionShare.vue';
import InstanceDiagnostics from './InstanceDiagnostics.vue';
const {state,selected,tab,versionsOpen,active,busy,running,tabs,statusLabel,rooms,room,guests,identity,settings,changes,connection,logs,roomTitle,native,settingGroups,flash,act,refresh,switchTab,selectRoom,action,newRoom,issue,revoke,toggle,accepting,saveSettings,saveConnection,copy,openRoom,openGame,rememberSelection,error}=useDesktop();
</script>
<template>
  <div v-if="active" class="instance-layout">
    <aside class="sidebar"><button class="back-button" @click="selected=null"><ArrowLeft :size="16"/>所有实例</button><div class="instance-heading"><div class="instance-symbol"><Flame :size="29"/></div><h2>{{active.name}}</h2><span :class="['status',active.status]"><i/>{{statusLabel[active.status]}}</span></div><nav><button v-for="item in tabs" :key="item.id" :class="{selected:tab===item.id}" @click="switchTab(item.id)"><component :is="item.icon" :size="18"/>{{item.name}}<ChevronRight v-if="tab===item.id" :size="14"/></button></nav><div class="sidebar-bottom"><p><ShieldCheck :size="14"/>管理权限只在本机</p><small>服务默认演示主持。真实模型与 TTS 可能收费，请只邀请可信同伴。</small></div></aside>
    <main class="workspace"><div v-if="state.desktop_updates?.available||active.update?.available" class="notice"><Download :size="18"/><p>{{state.desktop_updates?.available?'桌面新版本 '+state.desktop_updates.latest?.version:'游戏本体新版本 '+active.update?.latest?.version}}</p><button class="primary" @click="versionsOpen=true">查看并更新</button></div><div class="workspace-top"><div><span class="eyebrow">YOUR HOST, YOUR TABLE</span><h1>{{tabs.find(item=>item.id===tab)?.name}}</h1></div><div class="row"><button class="secondary" :disabled="busy" @click="refresh"><RefreshCw :size="15"/>刷新</button><button v-if="running" class="stop-button" :disabled="busy" @click="action('stop')"><Square :size="13"/>停止实例</button><button v-else class="primary" :disabled="busy" @click="action(active.commit?'start':'install')"><component :is="busy?LoaderCircle:Play" :size="15" :class="{spin:busy}"/>{{busy?'处理中…':active.commit?'启动实例':'安装并启动'}}</button></div></div>
      <section v-if="active.error" class="panel instance-failure" role="alert"><h3><TriangleAlert :size="18"/>酒馆需要处理</h3><p class="warning">{{active.error}}</p><p class="help-text">已有数据与备份保留。可查看任务记录或运行本机自检，确认后重试准备 / 启动。</p><button class="secondary" @click="switchTab('logs')">查看任务日志</button></section><div v-if="active.task" class="task-panel"><div><LoaderCircle class="spin" :size="18"/><b>{{active.task.stage}}</b><span>{{active.task.percent}}%</span></div><div class="progress"><i :style="{width:active.task.percent+'%'}"/></div><small>安装需要网络。可关闭控制台让任务在托盘继续；更新先备份，失败会回退。</small></div>
      <FirstTable v-if="tab==='setup'" :key="active.id" :instance="active" :native="native" @open="openRoom" @selected="rememberSelection" @error="error=$event" @message="flash"/><template v-if="tab==='overview'"><section class="welcome-panel"><div class="welcome-icon"><Flame :size="34"/></div><div><span class="eyebrow">THE TABLE IS WAITING</span><h2>{{running?'酒馆已经亮灯。':'在这里准备下一场冒险。'}}</h2><p>一个实例是一台酒馆服务器，可保存多间冒险房间。朋友连接同一个地址，不必各自安装。</p></div></section><div class="metric-grid"><article><small>本体版本</small><b>{{active.version||'尚未安装'}}</b><span>{{active.channel==='bundled'?'随桌面包固定版本':active.channel+' 通道'}}</span></article><article><small>游戏服务端口</small><b>{{active.port}}</b><span>单 worker · {{active.lan?'允许 LAN':'仅本机'}}</span></article><article><small>运行状态</small><b>{{statusLabel[active.status]}}</b><span>{{active.pid?'进程 '+active.pid:'数据不会因停止而删除'}}</span></article></div><section v-if="state.build" class="panel build-panel"><h3>桌面构建来源</h3><p class="help-text">桌面 {{state.build.desktop_version}} · 引擎 {{state.build.launcher_version}} · 打包本体 {{state.build.app_version}}</p><code>{{state.build.commit}}</code><p class="help-text">{{state.build.source_dirty?'开发构建含未提交改动，不能作为正式发布证据。':'来源由构建清单记录；安装的实例版本单独显示。'}}</p></section><section class="panel"><div class="panel-title"><h3><Wifi :size="17"/>同伴的浏览器入口</h3><span class="muted">不是 localhost，也不是 0.0.0.0</span></div><ConnectionShare :instance="active"/><p class="help-text">同伴使用你创建的身份＋专属密钥入座。系统防火墙需允许酒馆端口的私有网络访问；不会自动关闭防火墙。HTTP 不加密，远程请用 VPN／HTTPS。</p></section><InstanceDiagnostics :key="active.id" :instance-id="active.id"/><div class="quick-grid"><button class="panel quick" @click="switchTab('rooms')"><Users :size="24"/><b>准备房间与身份</b><p>创建冒险，再把同伴请到桌边。</p><ChevronRight :size="17"/></button><button class="panel quick" @click="switchTab('plugins')"><Blocks :size="24"/><b>按需添加能力</b><p>地图、声音与骰盘独立开关。</p><ChevronRight :size="17"/></button></div><div class="row"><button class="secondary" @click="versionsOpen=true"><History :size="15"/>切换版本</button><button class="secondary" :disabled="busy||!active.commit" @click="action('update')"><Download :size="15"/>更新到 GitHub 最新本体</button><button class="text-button" @click="action('folder')"><FolderOpen :size="16"/>打开数据目录</button></div></template>
      <template v-if="tab==='rooms'"><div v-if="!running" class="empty"><Users :size="32"/><h3>先让酒馆亮灯。</h3><p>安装／启动实例后，房主会自动登录本机专用账号。</p></div><template v-else><section class="panel"><h3>新建冒险房间</h3><form class="inline-form" @submit.prevent="newRoom"><input v-model="roomTitle" placeholder="例如：周末 · 雾港调查" maxlength="60" aria-label="房间名称"/><button class="primary" :disabled="busy"><Plus :size="16"/>创建房间</button></form><p class="help-text">先以演示主持开始；世界书、角色和真实模型模式在冒险桌内设置。</p></section><div class="room-select"><button v-for="item in rooms" :key="item.id" :class="{selected:room?.id===item.id}" @click="selectRoom(item.id)"><BookOpen :size="16"/>{{item.title}}</button></div><section v-if="room" class="panel"><div class="panel-title"><div><span class="eyebrow">CURRENT ADVENTURE</span><h2>{{room.title}}</h2></div><button class="primary" :disabled="busy||!native" @click="openGame"><Play :size="15"/>进入冒险桌</button></div><div class="room-summary"><span>{{room.state?.world?.title}}</span><span>{{Array.isArray(room.members)?room.members.length:room.members}} / 12 位成员</span><button class="text-button" :disabled="busy" @click="accepting">{{room.access?.accepting_players===false?'重新开放入座':'暂停新成员入座'}}</button></div><hr/><h3><KeyRound :size="17"/>同伴身份与验证密钥</h3><p class="help-text">每人一份可撤销的凭据。再次输入同一身份／密钥会回到同一位角色操控者，不需要注册账号。</p><form class="inline-form" @submit.prevent="issue"><input v-model="identity" placeholder="同伴身份，例如小王" maxlength="24" aria-label="同伴身份" required/><button class="secondary" :disabled="busy">生成专属密钥</button></form><div class="guest-row" v-for="guest in guests" :key="guest.id"><span class="identity-icon"><Users :size="15"/></span><div><b>{{guest.identity}}</b><small>{{guest.enabled?'可入座':'已撤销'}} · {{guest.user_id?'已经入座':'等待同伴'}} · {{guest.key_hint}}</small></div><button class="text-button" :disabled="busy" @click="identity=guest.identity;issue()"><RefreshCw :size="13"/>重新生成</button><button class="text-button danger" :disabled="busy||!guest.enabled" @click="revoke(guest)">撤销</button></div><p v-if="!guests.length" class="muted">还没有访客身份。密钥只生成时显示，不会在后续列表回显。</p><hr/><h3>在桌边的成员</h3><div class="members"><span v-for="member in Array.isArray(room.members)?room.members:[]" :key="member.id"><i :class="{online:member.online===true}"/>{{member.display_name}}<small>{{member.role==='host'?'房主':'玩家'}} · {{member.online===true?'在线':member.online===false?'离线':'连接状态未知'}}</small></span></div><p class="help-text">进入冒险桌后，在角色档案分配操控者。撤销访客会断开连接并解除角色分配；不会删除故事。</p></section></template></template>
      <template v-if="tab==='plugins'"><ModuleVersions v-if="native" :instance="active"/><section class="panel"><div class="panel-title"><h3><Blocks :size="18"/>扩展安装</h3><button class="secondary" :disabled="busy||running||!active.commit" @click="act('installPlugin')"><Plus :size="16"/>从本地 ZIP 安装</button></div><p class="help-text">先停止实例再安装。选择已审阅的包，确认 SHA256 与能力；Python 有完整服务器权限，不是沙箱。不会从任意 GitHub 自动下载执行。</p></section><div v-if="!running" class="empty"><Blocks :size="30"/><h3>启动后管理本房间的模块</h3><p>安装属于实例，开关属于房间；关闭不删除已有数据。</p></div><template v-else><div class="room-select"><button v-for="item in rooms" :key="item.id" :class="{selected:room?.id===item.id}" @click="selectRoom(item.id)">{{item.title}}</button></div><div v-if="!room" class="empty"><p>请先到房间与同伴创建一间房间。</p></div><div v-else class="plugins-grid"><article v-for="plugin in room.plugins" :key="plugin.id" class="panel plugin"><div class="panel-title"><Blocks :size="24"/><button class="switch" role="switch" :aria-checked="plugin.enabled" :aria-label="'开关 '+plugin.name" :disabled="busy||!!plugin.blocked" @click="toggle(plugin)"><i/></button></div><h3>{{plugin.name}}<small>v{{plugin.version}}</small></h3><p>{{plugin.description}}</p><footer><span>{{plugin.builtin?'随本体提供':'本机安装'}} · {{plugin.enabled?'本房开启':'数据保留'}}</span><code>{{plugin.id}}</code></footer><p v-if="plugin.blocked||plugin.fault" class="warning">{{plugin.blocked||plugin.fault}}</p></article></div></template></template>
      <template v-if="tab==='settings'"><ConnectionProfiles v-if="native" :key="active.id" :instance="active"/><div class="notice"><ShieldCheck :size="18"/><p>停止实例后才能修改运行配置。下方旧格式 API 配置保存在本机 settings.json 明文文件中，留作兼容；推荐使用上方加密连接档案。密钥不回显、不进入网页玩家端。默认演示不调用主持模型，其他模块的显式生成可独立收费。</p></div><section class="panel"><h3>实例与局域网</h3><form @submit.prevent="saveConnection" class="form"><div class="form-grid"><label>实例名称<input v-model="connection.name" :disabled="running||busy" maxlength="48"/></label><label>游戏端口<input v-model.number="connection.port" type="number" min="1024" max="65535" :disabled="running||busy"/></label></div><label class="checkbox"><input v-model="connection.lan" type="checkbox" :disabled="running||busy"/>允许同伴通过局域网浏览器入座</label><label>本体来源<select v-model="connection.channel" :disabled="running||busy"><option value="bundled">随此桌面包固定的兼容版本（推荐）</option><option value="main">GitHub main（显式信任最新源码）</option><option value="release">既有宿主 Release（可能不含桌面访客接口）</option></select></label><button class="secondary" :disabled="running||busy">保存网络与实例设置</button></form></section><p v-if="settings._desktop_profile_active" class="warning">此实例已应用加密连接档案。解除所有档案后才能编辑旧配置；密钥不会写入旧文件。</p><section v-for="group in settingGroups" :key="group.title" class="panel"><h3>{{group.title}}</h3><p class="help-text">{{group.note}}</p><div class="form form-grid"><label v-for="field in group.fields" :key="field[0]">{{field[1]}}<span v-if="field[2]==='password'" class="configured">{{settings[field[0]+'_configured']?'已配置 · 留空不修改':'未配置'}}</span><input :type="field[2]" :value="changes[field[0]]??(field[2]==='password'?'':settings[field[0]]||'')" :disabled="running||busy" :placeholder="field[2]==='password'?'输入新密钥；不填则保留':field[0].includes('BASE_URL')?'https://api.example.com/v1':field[1]" autocomplete="off" @input="changes[field[0]]=($event.target as HTMLInputElement).value"/><button v-if="field[2]==='password'&&settings[field[0]+'_configured']" class="text-button danger" :disabled="running||busy" @click="changes[field[0]]='';flash('保存时将清除此密钥')">清除此密钥</button></label></div></section><button class="primary" :disabled="running||busy||!!settings._desktop_profile_active||!Object.keys(changes).length" @click="saveSettings"><Check :size="16"/>保存 API 配置</button></template>
      <template v-if="tab==='logs'"><section class="panel"><div class="panel-title"><h3>安装／运行任务日志</h3><span class="muted">供应商密钥已过滤</span></div><pre class="log-console">{{logs.length?logs.join('\n'):'还没有运行日志。启动实例后可查看任务、依赖安装和服务消息。'}}</pre></section><p class="help-text">故障时保留数据与备份，不需要删库重装。完整运行日志在本机 launcher.log；分享前仍需检查个人信息。</p></template>
    </main>
  </div>

</template>
